#!/usr/bin/env python3
"""Trust boundary of both workflows generated by one Nix CI user policy."""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PIN = "070cb93f5972147ab0ed6efd1019e11ef6112a93"

def require(ok, message):
    if not ok:
        raise AssertionError(message)

def files():
    read = lambda path: (ROOT / path).read_text()
    return [
        read(".github/workflows/phenix-flake-ci-generated.yml"),
        read(".github/workflows/minimal-kernel-flake.yml"),
        read("ci/render-flake-workflows.nix"),
        read("ci/flake-check-config.nix"),
        read("flake.nix"),
        read(".github/workflows/minimal-kernel-dag.yml"),
        read(".github/workflows/p1-acp-sdk-interop.yml"),
        read(".github/workflows/verify-generated-flake-ci.yml"),
    ]

def verify(trusted, pr, renderer, config, flake, fallback, acp, verifier):
    require("mkFlakeCiWorkflows" in renderer,
            "consumer must generate both workflows from the library API")
    require("ci = (import ./flake-check-config.nix).ci;" in renderer,
            "workflow generator must use canonical Nix policy")
    require(f'libraryRef = "{PIN}";' in renderer, "source library pin changed")
    require("ci.mkFlakeCheckConfig" in config
            and "ci.rustCheckStrategy" in config,
            "check policy or Rust adapter removed")
    require('repository = "matthis-k/phenix-ai";' in config,
            "trusted repository identity changed")
    require('branches = [ "main" ];' in config,
            "Nix trust policy must declare exact trusted branches")
    require('pullRequest.backend = "nix-dag";' in config,
            "untrusted backend is not the full staged DAG")
    require('backend = "nix-remote";' in config
            and 'transport = "tailscale";' in config
            and 'credentials = "oidc";' in config
            and 'workers = 4;' in config
            and 'slotsPerWorker = 2;' in config,
            "native four-builder configuration changed")
    require("ci/flake-backend.nix" not in renderer
            and "mkFlakeCiWorkflow {" not in renderer,
            "old split backend declaration reintroduced")

    trusted_event = 'on:\n  push:\n    branches:\n      - "main"\n\npermissions:\n'
    require(trusted_event in trusted, "privileged trigger not restricted to exact push refs")
    require("  pull_request:" not in trusted and "  pull_request_target:" not in trusted
            and "  workflow_dispatch:" not in trusted and "  workflow_run:" not in trusted,
            "privileged workflow accepts an untrusted event or manual dispatch")
    require("permissions:\n  contents: read\n  id-token: write\n" in trusted,
            "OIDC permission unexpectedly altered")
    guard = (
        "    if: ${{ github.repository == 'matthis-k/phenix-ai' && "
        "(github.event_name == 'push' || github.event_name == 'workflow_dispatch') && "
        "(github.ref == 'refs/heads/main') }}"
    )
    require(guard in trusted, "trusted job admission lost repository/ref/event restrictions")
    require(trusted.count("flake-nix-builders.yml@" + PIN) == 1
            and trusted.count('library_ref: "' + PIN + '"') == 1,
            "trusted Nix reusable workflow and library are not pinned together")
    require('config: "ci/flake-check-config.nix"' in trusted,
            "trusted workflow changed check inventory")
    require("worker_count: 4\n      slots_per_worker: 2" in trusted,
            "trusted runner pool changed")
    require("TS_OAUTH_CLIENT_ID: ${{ secrets.TS_OAUTH_CLIENT_ID || vars.TS_OAUTH_CLIENT_ID }}" in trusted,
            "Tailscale OIDC client ID missing")
    require("TS_AUDIENCE: ${{ format('api.tailscale.com/{0}', secrets.TS_OAUTH_CLIENT_ID || vars.TS_OAUTH_CLIENT_ID) }}" in trusted,
            "Tailscale OIDC audience changed")
    require("TS_AUTHKEY:" not in trusted and "secrets: inherit" not in trusted,
            "broad credential forwarding reintroduced")

    require("on:\n  pull_request:\n\npermissions:\n  contents: read\n" in pr,
            "PR workflow no longer has only a read-only pull_request trigger")
    require("  push:" not in pr and "  workflow_dispatch:" not in pr
            and "  workflow_run:" not in pr and "  id-token: write" not in pr
            and "    secrets:" not in pr and "TS_" not in pr,
            "untrusted PR obtained credentials or trusted event")
    require(pr.count("flake-dag-staged.yml@" + PIN) == 1
            and pr.count('library_ref: "' + PIN + '"') == 1,
            "PR full-inventory backend pin differs from reviewed library")
    require('config: "ci/flake-check-config.nix"' in pr,
            "PR check inventory diverges from trusted check inventory")
    require("      publish:" not in pr and "secrets: inherit" not in pr,
            "PR backend may publish or inherit secrets")

    for check in ("p1-release-preflight", "m1-shipping", "basic-host-smoke",
                  "basic-pending-http-product", "m1-imports", "m1-public-sdk"):
        require(check in flake, "missing required complete Nix check: " + check)
    require("  pull_request:" not in fallback
            and "  workflow_dispatch:" in fallback
            and "id-token: write" not in fallback
            and "    secrets:" not in fallback,
            "fallback diagnostic obtained automatic authority")
    require("P1 official ACP SDK interop" in acp
            and "  pull_request:" in acp
            and "remote-phenix-m1-x86_64-linux-" in acp
            and "save: false" in acp,
            "independent ACP gate or read-only cache removed")
    require("ci/render-flake-workflows.nix" in verifier
            and "w: w.trusted" in verifier and "w: w.pullRequest" in verifier
            and "diff -u .github/workflows/minimal-kernel-flake.yml" in verifier
            and f"ref: {PIN}" in verifier,
            "generated workflow verification must check both outputs at same pin")

def self_test():
    good = files()
    verify(*good)
    mutations = [
        (0, '      - "main"', '      - "ci/untrusted"'),
        (0, '      - "main"', '      - "main"\n      - "ci/untrusted"'),
        (0, "on:\n  push:", "on:\n  pull_request:\n  push:"),
        (0, "  id-token: write", "  id-token: read"),
        (0, "github.repository == 'matthis-k/phenix-ai'", "true"),
        (0, "github.ref == 'refs/heads/main'", "true"),
        (0, "worker_count: 4", "worker_count: 8"),
        (0, "flake-nix-builders.yml@" + PIN, "flake-nix-builders.yml@" + "f"*40),
        (0, "      TS_OAUTH_CLIENT_ID:", "      TS_AUTHKEY:"),
        (1, "  contents: read", "  contents: read\n  id-token: write"),
        (1, "  pull_request:", "  pull_request:\n  workflow_dispatch:"),
        (1, "flake-dag-staged.yml@" + PIN, "flake-nix-builders.yml@" + PIN),
        (1, 'config: "ci/flake-check-config.nix"', 'config: "ci/reduced.nix"'),
        (2, "mkFlakeCiWorkflows", "mkFlakeCiWorkflow"),
        (2, "libraryRef = \"" + PIN + "\";", "libraryRef = \"main\";"),
        (3, 'branches = [ "main" ];',
             'branches = [ "main" "ci/untrusted" ];'),
        (4, "m1-shipping", "not-a-real-shipping-check"),
        (5, "  workflow_dispatch:", "  pull_request:\n  workflow_dispatch:"),
        (6, "save: false", "save: true"),
        (7, "w: w.pullRequest", "w: w.trusted"),
    ]
    for index, old, new in mutations:
        require(old in good[index], "bad adversarial fixture: " + old)
        modified = good.copy()
        modified[index] = modified[index].replace(old, new)
        try:
            verify(*modified)
        except AssertionError:
            pass
        else:
            raise AssertionError("unsafe CI policy mutation was admitted: " + old)

if __name__ == "__main__":
    if not sys.argv[1:]:
        verify(*files())
        print("PASS: paired trusted/PR execution policy and check inventory")
    elif sys.argv[1:] == ["--self-test"]:
        self_test()
        print("PASS: paired workflow policy adversarial tests")
    else:
        raise SystemExit("usage: ci-cutover-policy.py [--self-test]")
